examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchButton(
        text = {{askLabel}},
        onClick = {},
        modifier = Modifier.fillMaxWidth(),
        variant = MonarchButtonVariant.Secondary,
        size = MonarchButtonSize.Md,
    )
    MonarchCard(tone = MonarchTone.Ai) {
        MonarchAiOnboardingTour(
            steps = listOf(
                MonarchAiOnboardingTourStep({{steps.0.title}}, {{steps.0.body}}),
                MonarchAiOnboardingTourStep({{steps.1.title}}, {{steps.1.body}}),
                MonarchAiOnboardingTourStep({{steps.2.title}}, {{steps.2.body}}),
            ),
            onDisable = {},
            onFinish = {},
            onSkip = {},
        )
    }
}

examples.code:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    MonarchButton(
        text = "Ask the assistant",
        onClick = {},
        modifier = Modifier.fillMaxWidth(),
        variant = MonarchButtonVariant.Secondary,
        size = MonarchButtonSize.Md,
    )
    MonarchCard(tone = MonarchTone.Ai) {
        MonarchAiOnboardingTour(
            steps = listOf(
                MonarchAiOnboardingTourStep("What the assistant can see", "The page you have open, the records you select and any files you attach. It does not see other workspaces."),
                MonarchAiOnboardingTourStep("What it can do", "Summarise pages, draft text and answer questions about your records. It asks before it changes anything."),
                MonarchAiOnboardingTourStep("How to turn it off", "Use “Turn off AI” below at any time, or switch it off per app in workspace settings."),
            ),
            onDisable = {},
            onFinish = {},
            onSkip = {},
        )
    }
}
